{
  "name": "NaturistFinder",
  "description": "A comprehensive guide and map for finding naturist beaches, campsites, and resorts globally.",
  "requestFramePermissions": [
    "geolocation"
  ]
}

export interface NaturistLocation {
  id: string;
  name: string;
  type: 'beach' | 'resort' | 'campsite' | 'other';
  description: string;
  lat: number;
  lng: number;
  address?: string;
  rating?: number;
  url?: string;
  image?: string;
}

export interface SearchResult {
  locations: NaturistLocation[];
  summary: string;
  sources: { title: string; uri: string }[];
}

export enum LocationType {
  BEACH = 'beach',
  RESORT = 'resort',
  CAMPSITE = 'campsite',
  OTHER = 'other'
}

import { GoogleGenAI, Type } from "@google/genai";
import { NaturistLocation, SearchResult } from "./types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

export async function searchNaturistPlaces(
  query: string,
  userLocation?: { lat: number; lng: number }
): Promise<SearchResult> {
  const modelName = 'gemini-2.5-flash-lite-latest'; // Efficient for mapping tasks

  const systemInstruction = `
    You are an expert guide for naturist and nudist locations worldwide.
    Your task is to find specific naturist beaches, resorts, campsites, or clubs based on the user's query.
    For each location, provide:
    1. Name of the place.
    2. Category (beach, resort, campsite, or other).
    3. A brief, inviting description (approx 2 sentences).
    4. Approximate Latitude and Longitude.

    You MUST use Google Maps and Google Search grounding to find real, accurate locations.
    Format your response as a JSON object within your output if possible, but prioritize accuracy.
  `;

  const prompt = `Search for: "${query}". 
    ${userLocation ? `Prioritize locations near latitude ${userLocation.lat}, longitude ${userLocation.lng}.` : ''}
    Please return a list of at least 5 relevant naturist spots with their details.`;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: prompt,
      config: {
        systemInstruction,
        tools: [{ googleMaps: {} }, { googleSearch: {} }],
        toolConfig: {
          retrievalConfig: userLocation ? {
            latLng: {
              latitude: userLocation.lat,
              longitude: userLocation.lng
            }
          } : undefined
        }
      },
    });

    const text = response.text || "";
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    const sources = chunks
      .map(chunk => {
        if (chunk.maps) return { title: chunk.maps.title, uri: chunk.maps.uri };
        if (chunk.web) return { title: chunk.web.title, uri: chunk.web.uri };
        return null;
      })
      .filter((s): s is { title: string; uri: string } => !!s);

    // Use a secondary light-weight call to parse the unstructured text into JSON if needed,
    // but for performance, we'll use a regex-based extraction or simple parser.
    // In a production app, we'd use responseSchema, but responseSchema is not allowed with googleMaps.

    const parsedLocations = await extractLocationsFromText(text);

    return {
      locations: parsedLocations,
      summary: text,
      sources: sources
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

async function extractLocationsFromText(text: string): Promise<NaturistLocation[]> {
  // Use a quick follow-up prompt to structure the previous response
  // This is a common pattern when responseSchema isn't available with tools
  const parserModel = ai.models.generateContent({
    model: 'gemini-3-flash-preview',
    contents: `Extract the naturist locations mentioned in the following text into a JSON array. 
      Text: "${text}"`,
    config: {
      responseMimeType: "application/json",
      responseSchema: {
        type: Type.ARRAY,
        items: {
          type: Type.OBJECT,
          properties: {
            id: { type: Type.STRING },
            name: { type: Type.STRING },
            type: { type: Type.STRING, enum: ['beach', 'resort', 'campsite', 'other'] },
            description: { type: Type.STRING },
            lat: { type: Type.NUMBER },
            lng: { type: Type.NUMBER },
            address: { type: Type.STRING }
          },
          required: ['name', 'type', 'lat', 'lng', 'description']
        }
      }
    }
  });

  try {
    const result = await parserModel;
    const jsonStr = result.text.trim();
    const locations = JSON.parse(jsonStr);
    return locations.map((loc: any, index: number) => ({
      ...loc,
      id: loc.id || `loc-${index}`,
      image: `https://picsum.photos/seed/${encodeURIComponent(loc.name)}/400/300`
    }));
  } catch (e) {
    console.error("Parsing error:", e);
    return [];
  }
}

import React, { useEffect, useRef } from 'react';
import { NaturistLocation } from '../types';

interface MapProps {
  locations: NaturistLocation[];
  selectedLocation: NaturistLocation | null;
  onMarkerClick: (location: NaturistLocation) => void;
  center?: [number, number];
}

const Map: React.FC<MapProps> = ({ locations, selectedLocation, onMarkerClick, center }) => {
  const mapRef = useRef<L.Map | null>(null);
  const markersRef = useRef<{ [key: string]: L.Marker }>({});
  const mapContainerRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    if (!mapContainerRef.current) return;

    if (!mapRef.current) {
      mapRef.current = L.map(mapContainerRef.current).setView(center || [55.6761, 12.5683], 5);
      L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png', {
        attribution: '&copy; OpenStreetMap contributors'
      }).addTo(mapRef.current);
    }

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!mapRef.current) return;

    // Clear existing markers
    Object.values(markersRef.current).forEach(marker => marker.remove());
    markersRef.current = {};

    const bounds = L.latLngBounds([]);

    locations.forEach(loc => {
      const marker = L.marker([loc.lat, loc.lng])
        .addTo(mapRef.current!)
        .on('click', () => onMarkerClick(loc));

      marker.bindPopup(`<b>${loc.name}</b><br>${loc.type}`);
      markersRef.current[loc.id] = marker;
      bounds.extend([loc.lat, loc.lng]);
    });

    if (locations.length > 0) {
      mapRef.current.fitBounds(bounds, { padding: [50, 50] });
    }
  }, [locations]);

  useEffect(() => {
    if (selectedLocation && mapRef.current) {
      const { lat, lng } = selectedLocation;
      mapRef.current.setView([lat, lng], 14);
      const marker = markersRef.current[selectedLocation.id];
      if (marker) {
        marker.openPopup();
      }
    }
  }, [selectedLocation]);

  return <div ref={mapContainerRef} className="w-full h-full rounded-xl overflow-hidden shadow-inner border border-stone-200" />;
};

export default Map;

import React, { useState } from 'react';
import { Search, MapPin, Loader2 } from 'lucide-react';

interface SearchBarProps {
  onSearch: (query: string) => void;
  onLocateMe: () => void;
  isLoading: boolean;
}

const SearchBar: React.FC<SearchBarProps> = ({ onSearch, onLocateMe, isLoading }) => {
  const [query, setQuery] = useState('');

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      onSearch(query);
    }
  };

  return (
    <div className="w-full max-w-2xl mx-auto space-y-4">
      <form onSubmit={handleSubmit} className="relative group">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
          <Search className="h-5 w-5 text-stone-400 group-focus-within:text-emerald-500 transition-colors" />
        </div>
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder="Søg på land, by eller strandnavn..."
          className="block w-full pl-11 pr-24 py-4 bg-white border border-stone-200 rounded-2xl shadow-sm focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all text-stone-800 placeholder-stone-400"
        />
        <div className="absolute inset-y-0 right-2 flex items-center gap-2">
          <button
            type="button"
            onClick={onLocateMe}
            title="Brug min placering"
            className="p-2 text-stone-400 hover:text-emerald-600 hover:bg-stone-50 rounded-lg transition-colors"
          >
            <MapPin className="h-5 w-5" />
          </button>
          <button
            type="submit"
            disabled={isLoading || !query.trim()}
            className="px-5 py-2 bg-emerald-600 text-white font-medium rounded-xl hover:bg-emerald-700 disabled:opacity-50 disabled:cursor-not-allowed transition-all shadow-sm"
          >
            {isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'Søg'}
          </button>
        </div>
      </form>
    </div>
  );
};

export default SearchBar;

import React, { useState, useEffect, useCallback } from 'react';
import { Compass, Palmtree, Waves, Map as MapIcon, List, Info, ExternalLink, ShieldCheck } from 'lucide-react';
import Map from './components/Map';
import SearchBar from './components/SearchBar';
import { searchNaturistPlaces } from './geminiService';
import { NaturistLocation, SearchResult } from './types';

const App: React.FC = () => {
  const [locations, setLocations] = useState<NaturistLocation[]>([]);
  const [searchResult, setSearchResult] = useState<SearchResult | null>(null);
  const [selectedLocation, setSelectedLocation] = useState<NaturistLocation | null>(null);
  const [isLoading, setIsLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [userPos, setUserPos] = useState<{ lat: number; lng: number } | undefined>(undefined);
  const [viewMode, setViewMode] = useState<'split' | 'map' | 'list'>('split');

  const handleSearch = useCallback(async (query: string) => {
    setIsLoading(true);
    setError(null);
    try {
      const result = await searchNaturistPlaces(query, userPos);
      setLocations(result.locations);
      setSearchResult(result);
      if (result.locations.length > 0) {
        setSelectedLocation(null);
      }
    } catch (err) {
      setError("Der opstod en fejl under søgningen. Prøv igen senere.");
      console.error(err);
    } finally {
      setIsLoading(false);
    }
  }, [userPos]);

  const handleLocateMe = () => {
    if (navigator.geolocation) {
      setIsLoading(true);
      navigator.geolocation.getCurrentPosition(
        (pos) => {
          const coords = { lat: pos.coords.latitude, lng: pos.coords.longitude };
          setUserPos(coords);
          handleSearch("Naturist steder tæt på mig");
        },
        (err) => {
          setIsLoading(false);
          setError("Kunne ikke hente din placering.");
          console.warn(err);
        }
      );
    }
  };

  return (
    <div className="flex flex-col h-screen bg-stone-50 overflow-hidden">
      {/* Header */}
      <header className="bg-white border-b border-stone-200 px-6 py-4 flex items-center justify-between shrink-0 shadow-sm z-20">
        <div className="flex items-center gap-2">
          <div className="p-2 bg-emerald-100 rounded-lg">
            <Compass className="h-6 w-6 text-emerald-700" />
          </div>
          <div>
            <h1 className="text-xl font-bold text-stone-900 leading-none">NaturistFinder</h1>
            <p className="text-xs text-stone-500 font-medium">Find friheden i naturen</p>
          </div>
        </div>

        <div className="hidden md:flex items-center bg-stone-100 rounded-xl p-1">
          <button 
            onClick={() => setViewMode('split')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${viewMode === 'split' ? 'bg-white shadow-sm text-emerald-700' : 'text-stone-500 hover:text-stone-700'}`}
          >
            <MapIcon className="h-4 w-4" /> Split
          </button>
          <button 
            onClick={() => setViewMode('list')}
            className={`flex items-center gap-2 px-4 py-1.5 rounded-lg text-sm font-medium transition-all ${viewMode === 'list' ? 'bg-white shadow-sm text-emerald-700' : 'text-stone-500 hover:text-stone-700'}`}
          >
            <List className="h-4 w-4" /> Liste
          </button>
        </div>

        <div className="flex items-center gap-3">
          <div className="hidden sm:flex items-center gap-1 text-xs text-emerald-600 font-semibold bg-emerald-50 px-3 py-1.5 rounded-full border border-emerald-100">
            <ShieldCheck className="h-3.5 w-3.5" />
            Verificerede Steder
          </div>
        </div>
      </header>

      {/* Main Content */}
      <main className="flex-1 flex flex-col md:flex-row overflow-hidden relative">

        {/* Sidebar Search & List */}
        <div className={`flex-none w-full md:w-[450px] bg-white border-r border-stone-200 flex flex-col z-10 ${viewMode === 'map' ? 'hidden' : 'block'}`}>
          <div className="p-4 border-b border-stone-100 space-y-4 shadow-sm bg-stone-50/50">
            <SearchBar onSearch={handleSearch} onLocateMe={handleLocateMe} isLoading={isLoading} />
          </div>

          <div className="flex-1 overflow-y-auto p-4 space-y-4 no-scrollbar">
            {isLoading && (
              <div className="flex flex-col items-center justify-center py-20 text-stone-400 space-y-4">
                <div className="relative">
                  <div className="w-12 h-12 border-4 border-emerald-100 border-t-emerald-600 rounded-full animate-spin"></div>
                </div>
                <p className="text-sm animate-pulse font-medium">Finder de bedste naturist-oplevelser...</p>
              </div>
            )}

            {!isLoading && locations.length === 0 && !error && (
              <div className="flex flex-col items-center justify-center py-20 text-center space-y-4 px-6">
                <div className="p-4 bg-stone-100 rounded-full">
                  <Waves className="h-10 w-10 text-stone-300" />
                </div>
                <div>
                  <h3 className="text-lg font-semibold text-stone-700">Velkommen til NaturistFinder</h3>
                  <p className="text-sm text-stone-500 mt-2 max-w-xs">
                    Søg efter destinationer, lande eller specifikke strande for at starte din rejse.
                  </p>
                </div>
                <div className="flex flex-wrap justify-center gap-2 mt-4">
                  {['Danmark', 'Kroatien', 'Spanien', 'Frankrig'].map(tag => (
                    <button 
                      key={tag}
                      onClick={() => handleSearch(tag)}
                      className="px-4 py-2 bg-white border border-stone-200 rounded-lg text-sm text-stone-600 hover:border-emerald-300 hover:text-emerald-700 transition-colors shadow-sm"
                    >
                      {tag}
                    </button>
                  ))}
                </div>
              </div>
            )}

            {error && (
              <div className="p-4 bg-red-50 border border-red-100 rounded-xl text-red-600 text-sm flex items-center gap-3">
                <Info className="h-5 w-5 shrink-0" />
                <p>{error}</p>
              </div>
            )}

            {!isLoading && searchResult && (
              <div className="mb-6 px-2">
                <h2 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3">Søgeresultat</h2>
                <div className="bg-emerald-50/50 rounded-xl p-4 border border-emerald-100 text-sm text-stone-700 leading-relaxed italic">
                  "{searchResult.summary.split('\n')[0].substring(0, 150)}..."
                </div>
              </div>
            )}

            {locations.map((loc) => (
              <div 
                key={loc.id}
                onClick={() => setSelectedLocation(loc)}
                className={`group cursor-pointer bg-white border rounded-2xl overflow-hidden transition-all duration-300 hover:shadow-md ${selectedLocation?.id === loc.id ? 'border-emerald-500 ring-2 ring-emerald-50' : 'border-stone-200 hover:border-stone-300'}`}
              >
                <div className="relative h-40 overflow-hidden">
                  <img src={loc.image} alt={loc.name} className="w-full h-full object-cover transition-transform duration-500 group-hover:scale-105" />
                  <div className="absolute top-3 right-3">
                    <span className="px-3 py-1 bg-black/50 backdrop-blur-md text-white text-[10px] font-bold uppercase tracking-wider rounded-full border border-white/20">
                      {loc.type === 'beach' ? 'Strand' : loc.type === 'resort' ? 'Resort' : loc.type === 'campsite' ? 'Camping' : 'Andet'}
                    </span>
                  </div>
                </div>
                <div className="p-4">
                  <h3 className="font-bold text-stone-900 text-lg group-hover:text-emerald-700 transition-colors">{loc.name}</h3>
                  <p className="text-sm text-stone-500 mt-1 line-clamp-2 leading-relaxed">{loc.description}</p>

                  <div className="mt-4 pt-4 border-t border-stone-100 flex items-center justify-between">
                    <div className="flex items-center gap-1.5 text-stone-400 text-xs">
                      <MapIcon className="h-3.5 w-3.5" />
                      <span>{loc.lat.toFixed(3)}, {loc.lng.toFixed(3)}</span>
                    </div>
                    {loc.address && (
                       <span className="text-xs text-stone-500 truncate max-w-[200px]">{loc.address}</span>
                    )}
                  </div>
                </div>
              </div>
            ))}

            {searchResult && searchResult.sources.length > 0 && (
              <div className="pt-6 pb-10">
                <h4 className="text-xs font-bold text-stone-400 uppercase tracking-widest mb-3 px-2">Kilder</h4>
                <div className="flex flex-wrap gap-2 px-2">
                  {searchResult.sources.map((source, i) => (
                    <a 
                      key={i} 
                      href={source.uri} 
                      target="_blank" 
                      rel="noopener noreferrer"
                      className="inline-flex items-center gap-1.5 px-3 py-1.5 bg-stone-100 rounded-lg text-xs text-stone-600 hover:bg-stone-200 transition-colors"
                    >
                      <ExternalLink className="h-3 w-3" />
                      {source.title || 'Kilde'}
                    </a>
                  ))}
                </div>
              </div>
            )}
          </div>
        </div>

        {/* Map View */}
        <div className={`flex-1 relative ${viewMode === 'list' ? 'hidden md:block' : 'block'}`}>
          <Map 
            locations={locations} 
            selectedLocation={selectedLocation} 
            onMarkerClick={setSelectedLocation}
            center={userPos ? [userPos.lat, userPos.lng] : undefined}
          />

          {/* Mobile Toggle Button */}
          <div className="absolute bottom-6 left-1/2 -translate-x-1/2 md:hidden z-20">
            <button 
              onClick={() => setViewMode(viewMode === 'map' ? 'list' : 'map')}
              className="flex items-center gap-2 px-6 py-3 bg-stone-900 text-white rounded-full shadow-2xl font-bold transition-transform active:scale-95"
            >
              {viewMode === 'map' ? <><List className="h-5 w-5" /> Se Liste</> : <><MapIcon className="h-5 w-5" /> Se Kort</>}
            </button>
          </div>
        </div>
      </main>

      {/* Floating Info Section */}
      {selectedLocation && (
        <div className="fixed bottom-20 md:bottom-10 right-4 md:right-10 w-[90vw] md:w-96 bg-white rounded-3xl shadow-2xl border border-emerald-100 z-30 animate-in slide-in-from-bottom-10">
          <div className="p-6">
            <div className="flex justify-between items-start mb-4">
              <span className="px-3 py-1 bg-emerald-100 text-emerald-700 text-[10px] font-bold uppercase rounded-full">
                {selectedLocation.type}
              </span>
              <button onClick={() => setSelectedLocation(null)} className="text-stone-400 hover:text-stone-600">
                <Waves className="h-6 w-6 rotate-45" />
              </button>
            </div>
            <h2 className="text-2xl font-bold text-stone-900 mb-2">{selectedLocation.name}</h2>
            <p className="text-sm text-stone-600 leading-relaxed mb-6">{selectedLocation.description}</p>

            <div className="grid grid-cols-2 gap-3">
              <a 
                href={`https://www.google.com/maps/dir/?api=1&destination=${selectedLocation.lat},${selectedLocation.lng}`}
                target="_blank"
                rel="noopener noreferrer"
                className="flex items-center justify-center gap-2 px-4 py-3 bg-emerald-600 text-white rounded-2xl font-bold text-sm hover:bg-emerald-700 transition-colors shadow-lg shadow-emerald-200"
              >
                Rutevejledning
              </a>
              <button 
                className="flex items-center justify-center gap-2 px-4 py-3 bg-stone-100 text-stone-700 rounded-2xl font-bold text-sm hover:bg-stone-200 transition-colors"
              >
                Gem Sted
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
