import { GoogleGenAI, Type } from "@google/genai";
import { NaturistLocation, SearchResult } from "./types";

// Simpel in-memory cache for søgeforslag
const suggestionCache = new Map<string, string[]>();

export async function getSuggestions(query: string): Promise<string[]> {
  const trimmedQuery = query.trim().toLowerCase();
  if (trimmedQuery.length < 2) return [];

  if (suggestionCache.has(trimmedQuery)) {
    return suggestionCache.get(trimmedQuery)!;
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Giv 5 korte forslag til geografiske destinationer (byer, øer, lande) der starter med eller minder om: "${query}". Returner kun en JSON liste af strenge.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    suggestionCache.set(trimmedQuery, results);
    return results;
  } catch (e) {
    console.error("Suggestion error:", e);
    return [];
  }
}

export async function searchNaturistPlaces(
  query: string,
  userLocation?: { lat: number; lng: number }
): Promise<SearchResult> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelName = 'gemini-2.5-flash';

  const systemInstruction = `
    Du er en ekspert i naturisme og rejse-sikkerhed. Find naturiststeder (strande, resorts, camping) for: "${query}".

    VIGTIGT: Hvis området eller landet har strenge love imod naturisme eller offentlig nøgenhed (f.eks. De Forenede Arabiske Emirater, visse konservative regioner), skal du inkludere en MEGET TYDELIG advarsel i feltet 'warning'. 
    Forklar kort alvoren af reglerne (f.eks. fængselsstraf eller udvisning).

    For hvert sted skal du give:
    1. Navn.
    2. Type (beach, resort, campsite, other).
    3. Beskrivelse (2-3 sætninger).
    4. Koordinater (lat/lng).
    5. Officiel adresse hvis muligt.
    6. URL til et billede KUN hvis du er helt sikker på det er et specifikt billede af stedet.
    7. Warning (valgfri): Juridisk eller sikkerhedsmæssig advarsel.

    Brug Google Maps og Search grounding.
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: `Søg efter naturiststeder i: ${query}`,
      config: {
        systemInstruction,
        tools: [{ googleMaps: {} }, { googleSearch: {} }],
      },
    });

    const text = response.text || "";
    const parsedLocations = await extractLocationsFromText(text);

    return {
      locations: parsedLocations,
      summary: text,
      sources: []
    };
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

async function extractLocationsFromText(text: string): Promise<NaturistLocation[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Ekstraher steder fra denne tekst til JSON. Sørg for at 'warning' feltet medtages hvis det findes: "${text}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              type: { type: Type.STRING, enum: ['beach', 'resort', 'campsite', 'other'] },
              description: { type: Type.STRING },
              lat: { type: Type.NUMBER },
              lng: { type: Type.NUMBER },
              address: { type: Type.STRING },
              image: { type: Type.STRING },
              warning: { type: Type.STRING }
            },
            required: ['name', 'type', 'lat', 'lng', 'description']
          }
        }
      }
    });

    const locations = JSON.parse(result.text.trim());
    return locations.map((loc: any, index: number) => ({
      ...loc,
      id: loc.id || `loc-${index}`,
    }));
  } catch (e) {
    return [];
  }
}

import React, { useState, useEffect, useRef } from 'react';
import { Search, MapPin, Loader2, X } from 'lucide-react';
import { getSuggestions } from '../geminiService';

interface SearchBarProps {
  onSearch: (query: string) => void;
  onLocateMe: () => void;
  isLoading: boolean;
}

const SearchBar: React.FC<SearchBarProps> = ({ onSearch, onLocateMe, isLoading }) => {
  const [query, setQuery] = useState('');
  const [suggestions, setSuggestions] = useState<string[]>([]);
  const [showSuggestions, setShowSuggestions] = useState(false);
  const [isSearchingSuggestions, setIsSearchingSuggestions] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const timer = setTimeout(async () => {
      if (query.trim().length >= 2) {
        setIsSearchingSuggestions(true);
        const results = await getSuggestions(query);
        setSuggestions(results);
        setShowSuggestions(results.length > 0);
        setIsSearchingSuggestions(false);
      } else {
        setSuggestions([]);
        setShowSuggestions(false);
        setIsSearchingSuggestions(false);
      }
    }, 300);

    return () => clearTimeout(timer);
  }, [query]);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (dropdownRef.current && !dropdownRef.current.contains(event.target as Node)) {
        setShowSuggestions(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    if (query.trim()) {
      onSearch(query);
      setShowSuggestions(false);
    }
  };

  const handleSelectSuggestion = (s: string) => {
    setQuery(s);
    onSearch(s);
    setShowSuggestions(false);
  };

  return (
    <div className="w-full max-w-2xl mx-auto relative" ref={dropdownRef}>
      <form onSubmit={handleSubmit} className="relative group">
        <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
          {isSearchingSuggestions ? (
            <Loader2 className="h-5 w-5 text-emerald-500 animate-spin" />
          ) : (
            <Search className="h-5 w-5 text-stone-400 group-focus-within:text-emerald-500 transition-colors" />
          )}
        </div>
        <input
          type="text"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          onFocus={() => query.length >= 2 && setShowSuggestions(true)}
          placeholder="Søg destination (f.eks. Korsika)..."
          className="block w-full pl-11 pr-24 py-4 bg-white border border-stone-200 rounded-2xl shadow-sm focus:ring-2 focus:ring-emerald-500 focus:border-emerald-500 outline-none transition-all text-stone-800 placeholder-stone-400"
        />
        <div className="absolute inset-y-0 right-2 flex items-center gap-2">
          {query && (
            <button
              type="button"
              onClick={() => setQuery('')}
              className="p-1 text-stone-300 hover:text-stone-500 rounded-full"
            >
              <X className="h-4 w-4" />
            </button>
          )}
          <button
            type="button"
            onClick={onLocateMe}
            className="p-2 text-stone-400 hover:text-emerald-600 hover:bg-stone-50 rounded-lg transition-colors"
          >
            <MapPin className="h-5 w-5" />
          </button>
          <button
            type="submit"
            disabled={isLoading || !query.trim()}
            className="px-5 py-2 bg-emerald-600 text-white font-medium rounded-xl hover:bg-emerald-700 disabled:opacity-50 transition-all shadow-sm"
          >
            {isLoading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'Søg'}
          </button>
        </div>
      </form>

      {showSuggestions && (
        <div className="absolute w-full mt-2 bg-white border border-stone-100 rounded-2xl shadow-2xl z-50 overflow-hidden animate-in fade-in slide-in-from-top-2 duration-200">
          <div className="py-2">
            {suggestions.map((s, idx) => (
              <button
                key={idx}
                onClick={() => handleSelectSuggestion(s)}
                className="w-full text-left px-5 py-3 hover:bg-emerald-50 text-stone-700 font-medium flex items-center gap-3 transition-colors border-b border-stone-50 last:border-0"
              >
                <Search className="h-4 w-4 text-emerald-400" />
                {s}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  );
};

export default SearchBar;

import React, { useEffect, useRef } from 'react';
import * as L from 'leaflet';
import { NaturistLocation } from '../types';

interface MapProps {
  locations: NaturistLocation[];
  selectedLocation: NaturistLocation | null;
  onMarkerClick: (location: NaturistLocation) => void;
  center?: [number, number];
}

const Map: React.FC<MapProps> = ({ locations, selectedLocation, onMarkerClick, center }) => {
  const mapRef = useRef<L.Map | null>(null);
  const mapContainerRef = useRef<HTMLDivElement>(null);
  const markersLayerRef = useRef<L.LayerGroup | null>(null);

  // Custom ikoner til advarsler
  const createIcon = (color: string) => {
    return L.divIcon({
      className: 'custom-div-icon',
      html: `<div style="background-color: ${color}; width: 14px; height: 14px; border: 3px solid white; border-radius: 50%; box-shadow: 0 0 10px rgba(0,0,0,0.3);"></div>`,
      iconSize: [20, 20],
      iconAnchor: [10, 10],
    });
  };

  const defaultIcon = createIcon('#059669'); // Emerald
  const warningIcon = createIcon('#ef4444'); // Red

  useEffect(() => {
    if (!mapContainerRef.current || mapRef.current) return;

    mapRef.current = L.map(mapContainerRef.current, {
      zoomControl: false
    }).setView(center || [55.6761, 12.5683], 5);

    L.tileLayer('https://{s}.basemaps.cartocdn.com/rastertiles/voyager/{z}/{x}/{y}{r}.png', {
      attribution: '&copy; OpenStreetMap contributors &copy; CARTO'
    }).addTo(mapRef.current);

    L.control.zoom({ position: 'bottomright' }).addTo(mapRef.current);
    markersLayerRef.current = L.layerGroup().addTo(mapRef.current);

    return () => {
      if (mapRef.current) {
        mapRef.current.remove();
        mapRef.current = null;
      }
    };
  }, []);

  useEffect(() => {
    if (!mapRef.current || !markersLayerRef.current) return;

    markersLayerRef.current.clearLayers();
    const bounds = L.latLngBounds([]);

    locations.forEach(loc => {
      const marker = L.marker([loc.lat, loc.lng], {
        icon: loc.warning ? warningIcon : defaultIcon
      }).on('click', () => onMarkerClick(loc));

      const popupContent = `
        <div class="p-2">
          <b class="text-stone-900">${loc.name}</b><br>
          <span class="text-xs text-stone-500">${loc.type === 'beach' ? 'Strand' : 'Sted'}</span>
          ${loc.warning ? `<div class="mt-2 p-1.5 bg-red-50 text-red-600 text-[10px] font-bold rounded border border-red-100">⚠️ ADVARSEL</div>` : ''}
        </div>
      `;
      marker.bindPopup(popupContent);
      markersLayerRef.current?.addLayer(marker);
      bounds.extend([loc.lat, loc.lng]);
    });

    if (locations.length > 0) {
      mapRef.current.fitBounds(bounds, { padding: [50, 50], maxZoom: 12 });
    }
  }, [locations]);

  useEffect(() => {
    if (selectedLocation && mapRef.current) {
      mapRef.current.flyTo([selectedLocation.lat, selectedLocation.lng], 13, { duration: 1.5 });
    }
  }, [selectedLocation]);

  return (
    <div className="relative w-full h-full">
      <div ref={mapContainerRef} className="absolute inset-0 z-0" />
    </div>
  );
};

export default Map;

