import { GoogleGenAI, Type } from "@google/genai";
import { NaturistLocation, SearchResult } from "./types";

// Cache for søgeforslag og søgeresultater
const suggestionCache = new Map<string, string[]>();
const searchCache = new Map<string, SearchResult>();

export async function getSuggestions(query: string): Promise<string[]> {
  const trimmedQuery = query.trim().toLowerCase();
  if (trimmedQuery.length < 2) return [];

  if (suggestionCache.has(trimmedQuery)) {
    return suggestionCache.get(trimmedQuery)!;
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Giv 5 korte, præcise forslag til geografiske destinationer (byer, øer, lande) der starter med eller minder om: "${query}". Returner kun en JSON liste af strenge på dansk.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: { type: Type.STRING }
        }
      }
    });

    const results = JSON.parse(response.text || "[]");
    suggestionCache.set(trimmedQuery, results);
    return results;
  } catch (e) {
    console.error("Suggestion error:", e);
    return [];
  }
}

export async function searchNaturistPlaces(
  query: string,
  userLocation?: { lat: number; lng: number }
): Promise<SearchResult> {
  const cacheKey = `${query.toLowerCase().trim()}_${userLocation ? 'loc' : 'none'}`;

  if (searchCache.has(cacheKey)) {
    return searchCache.get(cacheKey)!;
  }

  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  const modelName = 'gemini-2.5-flash';

  const systemInstruction = `
    Du er en rejseguide specialiseret i naturisme. Din opgave er at finde og liste mindst 5 specifikke naturiststeder (strande, resorts, campingpladser) for den forespurgte destination.

    VIGTIGE REGLER:
    1. Søg grundigt efter eksisterende faciliteter. For Korsika skal du f.eks. finde steder som Riva Bella, Bagheera eller La Chiappa.
    2. Hvis destinationen er et land/område hvor naturisme er STRENGT FORBUDT ved lov (f.eks. Dubai/UAE, Saudi Arabien), skal du IKKE opfinde steder, men i stedet returnere ét "advarsels-punkt" for hele destinationen med en forklaring i feltet 'warning'.
    3. Tilføj KUN en 'warning' hvis lovgivningen i landet gør naturisme farligt eller ulovligt. Tilføj ALDRIG advarsler på lovlige steder i lande som Frankrig, Danmark, Tyskland osv.

    For hvert sted skal du inkludere: Navn, Type, Beskrivelse, Koordinater, Adresse, og Billede-URL (kun hvis verificeret).
  `;

  try {
    const response = await ai.models.generateContent({
      model: modelName,
      contents: `Find og beskriv mindst 5 populære naturist-steder i eller omkring: ${query}. Hvis landet/området generelt forbyder naturisme, så forklar dette tydeligt.`,
      config: {
        systemInstruction,
        tools: [{ googleMaps: {} }, { googleSearch: {} }],
      },
    });

    const text = response.text || "";
    const parsedLocations = await extractLocationsFromText(text);

    const result = {
      locations: parsedLocations,
      summary: text,
      sources: []
    };

    if (parsedLocations.length > 0) {
      searchCache.set(cacheKey, result);
    }
    return result;
  } catch (error) {
    console.error("Gemini API Error:", error);
    throw error;
  }
}

async function extractLocationsFromText(text: string): Promise<NaturistLocation[]> {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
  try {
    const result = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `Ekstraher naturist-lokationer fra denne tekst til et validt JSON array. Sørg for at 'warning' feltet kun medtages hvis teksten nævner juridiske forbud eller risici for hele området/landet: "${text}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.ARRAY,
          items: {
            type: Type.OBJECT,
            properties: {
              id: { type: Type.STRING },
              name: { type: Type.STRING },
              type: { type: Type.STRING, enum: ['beach', 'resort', 'campsite', 'other'] },
              description: { type: Type.STRING },
              lat: { type: Type.NUMBER },
              lng: { type: Type.NUMBER },
              address: { type: Type.STRING },
              image: { type: Type.STRING },
              warning: { type: Type.STRING }
            },
            required: ['name', 'type', 'lat', 'lng', 'description']
          }
        }
      }
    });

    const locations = JSON.parse(result.text.trim());
    return locations.map((loc: any, index: number) => ({
      ...loc,
      id: loc.id || `loc-${index}`,
    }));
  } catch (e) {
    console.error("Extraction error:", e);
    return [];
  }
}

